public class WorkerPool {

    private final TaskQueue queue;
    private final int workerCount;
    private int total;
    private int processed;

    public WorkerPool(TaskQueue queue, int requestedWorkers) {
        this.queue = queue;
        this.workerCount = Math.max(1, Math.min(8, requestedWorkers));
    }

    public int workerCount() {
        return workerCount;
    }

    public void run() throws InterruptedException {
        Thread[] workers = new Thread[workerCount];
        for (int i = 0; i < workerCount; i++) {
            workers[i] = new Thread(new Runnable() {
                @Override
                public void run() {
                    Integer task = queue.take();
                    while (task != null) {
                        record(task);
                        task = queue.take();
                    }
                }
            });
        }
        for (Thread worker : workers) {
            worker.start();
        }
        for (Thread worker : workers) {
            worker.join();
        }
    }

    /** Called by the workers: must be safe when several threads call it at once. */
    private synchronized void record(int task) {
        total += task * task;
        processed++;
    }

    public synchronized int total() {
        return total;
    }

    public synchronized int processed() {
        return processed;
    }
}

