public class WorkerPoolTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static TaskQueue queueOf(int from, int to) {
        TaskQueue queue = new TaskQueue();
        for (int i = from; i <= to; i++) {
            queue.add(i);
        }
        return queue;
    }

    public static void main(String[] args) throws Exception {
        TaskQueue small = queueOf(2, 3);
        check("remaining after two adds", 2, small.remaining());
        check("first task taken", Integer.valueOf(2), small.take());
        check("second task taken", Integer.valueOf(3), small.take());
        check("taking from an empty queue", null, small.take());
        check("taken count", 2, small.takenCount());
        check("remaining once drained", 0, small.remaining());

        TaskQueue queue = queueOf(1, 3);
        WorkerPool pool = new WorkerPool(queue, 2);
        pool.run();
        check("sum of squares of 1..3", 14, pool.total());
        check("tasks processed", 3, pool.processed());
        check("queue drained by the workers", 0, queue.remaining());

        TaskQueue big = queueOf(1, 1000);
        WorkerPool busy = new WorkerPool(big, 4);
        busy.run();
        check("sum of squares of 1..1000", 333833500, busy.total());
        check("every task processed exactly once", 1000, busy.processed());
        check("no task was handed out twice", 1000, big.takenCount());

        check("worker count is clamped down", 8, new WorkerPool(queueOf(1, 1), 100).workerCount());
        check("worker count is clamped up", 1, new WorkerPool(queueOf(1, 1), 0).workerCount());

        WorkerPool idle = new WorkerPool(new TaskQueue(), 3);
        idle.run();
        check("an empty queue finishes with nothing done", 0, idle.processed());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

